```ts
'use server';

export async function updateProduct(id, formData) {
  const user = await requireUser();
  await requireProductEditor(user, id);
  const input = productSchema.parse(Object.fromEntries(formData));
  await db.product.update({ where: { id }, data: input });
  revalidateTag(`product:${id}`);
}
```

Client-provided ID and form fields are validated and authorized inside the action.
